<?php $products=$products??[]; ?>
<section class="ca-card"><div class="ca-card-head"><h2>Tu colección de compras</h2><span class="ca-note"><?= count($products) ?> productos</span></div>
<?php if(!$products): ?><div class="ca-empty"><i class="fa-solid fa-bag-shopping"></i><h3 class="h6 fw-bold text-dark">Aún no tienes productos comprados</h3><p>Los productos de tus pedidos aparecerán aquí.</p><a class="ca-button" href="<?= APP_URL ?>/tienda">Explorar productos</a></div>
<?php else: ?><div class="ca-product-grid"><?php foreach($products as $p): $image=$p['image_path']??''; ?><article class="ca-product"><?php if($image): ?><img src="<?= APP_URL ?>/public/<?= htmlspecialchars(ltrim($image,'/'),ENT_QUOTES,'UTF-8') ?>" alt="<?= htmlspecialchars($p['item_name'],ENT_QUOTES,'UTF-8') ?>"><?php else: ?><div class="ca-avatar"><i class="fa-solid fa-burger"></i></div><?php endif; ?><div class="flex-grow-1"><strong><?= htmlspecialchars($p['item_name'],ENT_QUOTES,'UTF-8') ?></strong><small>Comprados: <?= (int)$p['quantity_purchased'] ?><br>Última compra: <?= date('d/m/Y',strtotime($p['last_purchased_at'])) ?></small></div><strong><?= $caMoney($p['last_unit_price']) ?></strong></article><?php endforeach; ?></div><?php endif; ?></section>